        if ($emailAccountUsuario) {
            $this->addUsingAlias(EmailAccountUsuarioPeer::EMAILACCOUNTUSUARIO_ID, $emailAccountUsuario->getEmailaccountusuarioId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

